WITH flattened_attrs AS (SELECT id, plan, effective_from, discounts, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers WHERE effective_from < '2024-03-20') SELECT *, LEAD(entry_price, 1) OVER (ORDER BY effective_from, id) AS next_entry_price, SUM(entry_price) OVER (PARTITION BY plan) AS plan_sum_entry_price, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY entry_price DESC NULLS FIRST) AS entry_price_percent_rank, AVG(lowest_price) OVER (PARTITION BY plan ORDER BY effective_from, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS lowest_price_avg_6 FROM flattened_attrs WHERE lowest_price < 12
